
        const INS = [{ "id": "ins-selatan-01", "wil": "Jakarta Selatan", "lbl": "PENERIMAAN PAJAK", "angka": "Rp 16,77 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Selatan mencapai Rp 16,77 Triliun pada tahun 2023, menjadikannya wilayah pemungutan pajak terbesar dengan kontribusi sekitar 32% dari seluruh penerimaan pajak daerah DKI Jakarta.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-selatan-02", "wil": "Jakarta Selatan", "lbl": "PAJAK BUMI & BANGUNAN", "angka": "Rp 3,85 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Selatan dari sektor Pajak Bumi dan Bangunan (PBB-P2) mencapai Rp 3,85 Triliun di tahun 2023, ditopang oleh kawasan hunian mapan dan koridor perkantoran TB Simatupang.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-pusat-01", "wil": "Jakarta Pusat", "lbl": "PENERIMAAN PAJAK", "angka": "Rp 14,67 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Pusat mencapai Rp 14,67 Triliun pada tahun 2023, merefleksikan tingginya aktivitas komersial di kawasan Thamrin, Sudirman, dan pusat pemerintahan.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-pusat-02", "wil": "Jakarta Pusat", "lbl": "PAJAK HOTEL", "angka": "Rp 586 Miliar", "teks": "Pajak yang terkumpul di wilayah Jakarta Pusat dari sektor perhotelan mencapai Rp 586 Miliar pada 2023, tertinggi di antara seluruh wilayah kota administrasi berkat kegiatan konvensi dan pariwisata pusat kota.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-barat-01", "wil": "Jakarta Barat", "lbl": "PENERIMAAN PAJAK", "angka": "Rp 9,43 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Barat tercatat sebesar Rp 9,43 Triliun pada 2023, dengan kontribusi kuat dari sektor pajak kendaraan bermotor dan restoran di kawasan perdagangan Puri dan Grogol.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-barat-02", "wil": "Jakarta Barat", "lbl": "PAJAK KENDARAAN BERMOTOR", "angka": "Rp 1,69 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Barat untuk Pajak Kendaraan Bermotor (PKB) menyumbang Rp 1,69 Triliun di tahun 2023, menandakan tingkat kepemilikan dan kepatuhan perpanjangan STNK yang dinamis.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-timur-01", "wil": "Jakarta Timur", "lbl": "PENERIMAAN PAJAK", "angka": "Rp 6,28 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Timur membukukan nilai Rp 6,28 Triliun pada tahun 2023, dengan porsi terbesar berasal dari Pajak Kendaraan Bermotor dan PBB kawasan industri Pulogadung.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-utara-01", "wil": "Jakarta Utara", "lbl": "PENERIMAAN PAJAK", "angka": "Rp 5,13 Triliun", "teks": "Pajak yang terkumpul di wilayah Jakarta Utara mencapai Rp 5,13 Triliun pada tahun 2023, didorong oleh aktivitas logistik pergudangan Tanjung Priok, kawasan Kelapa Gading, dan perumahan pesisir Pluit.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-seribu-01", "wil": "Kepulauan Seribu", "lbl": "PENERIMAAN PAJAK", "angka": "Rp 104,8 Miliar", "teks": "Pajak yang terkumpul di wilayah Kepulauan Seribu mencapai Rp 104,8 Miliar pada tahun 2023, dengan mayoritas penerimaan berasal dari pajak resor wisata bahari, restoran kepulauan, dan PBB pulau resort.", "sumber": "satudatajakarta.go.id", "thn": 2023, "ver": true }, { "id": "ins-belanja-dishub", "wil": "Seluruh DKI Jakarta", "lbl": "BELANJA PERHUBUNGAN", "angka": "Rp 6,12 Triliun", "teks": "Secara keseluruhan se-Jakarta, realisasi belanja Dinas Perhubungan mencapai Rp 6,12 Triliun (95,92% dari pagu) untuk menjaga subsidi tarif Transjakarta, MRT, dan LRT agar tetap terjangkau bagi warga.", "sumber": "satudatajakarta.go.id / BPKAD", "thn": 2023, "ver": true }, { "id": "ins-belanja-disdik", "wil": "Seluruh DKI Jakarta", "lbl": "BELANJA PENDIDIKAN", "angka": "Rp 16,98 Triliun", "teks": "Anggaran belanja sektor pendidikan se-Jakarta terealisasi sebesar Rp 16,98 Triliun pada 2023, membiayai program KJP Plus bagi ratusan ribu pelajar dan rehabilitasi puluhan gedung sekolah ramah lingkungan.", "sumber": "satudatajakarta.go.id / BPKAD", "thn": 2023, "ver": true }, { "id": "ins-belanja-dsda", "wil": "Seluruh DKI Jakarta", "lbl": "BELANJA SUMBER DAYA AIR", "angka": "Rp 4,73 Triliun", "teks": "Realisasi belanja Dinas Sumber Daya Air se-Jakarta mencapai Rp 4,73 Triliun pada tahun 2023, difokuskan pada pemeliharaan polder air, tanggul pantai NCICD, dan pengerukan lumpur saluran makro.", "sumber": "satudatajakarta.go.id / BPKAD", "thn": 2023, "ver": true }];
