// --- Card Generator UI Controller (Reference Layout) ---
let curTemplate = 'sunburst';
let curRegion = 'Jakarta Selatan';
let curIndex = 0;
let curName = 'Raihan';

function getFilteredInsights(region) {
  if (!region || region === 'Semua Wilayah') return INS;
  return INS.filter(item => item.wil === region);
}

function renderCardPreview() {
  const mountEl = document.getElementById('card-mount-point');
  if (!mountEl) return;
  const currentData = { ...INS[curIndex], nm: curName || 'Warga Jakarta' };
  mount(mountEl, curTemplate, currentData);
  updateCardPreviewScale();
}

function updateCardPreviewScale() {
  const viewport = document.getElementById('card-preview-viewport');
  const wrapper = document.getElementById('card-preview-scale-wrapper');
  if (!viewport || !wrapper) return;
  const availableWidth = viewport.clientWidth;
  if (!availableWidth) return;
  const scale = availableWidth / 540;
  wrapper.style.transform = 'scale(' + scale + ')';
  viewport.style.height = Math.round(760 * scale) + 'px';
}

function populateInsightDropdown() {
  const select = document.getElementById('card-insight-select');
  if (!select) return;
  select.innerHTML = '';
  const list = getFilteredInsights(curRegion);
  list.forEach(item => {
    const originalIdx = INS.findIndex(i => i.id === item.id);
    const opt = document.createElement('option');
    opt.value = originalIdx;
    opt.textContent = '[' + item.wil + '] ' + item.lbl + ' (' + item.angka + ')';
    if (originalIdx === curIndex) opt.selected = true;
    select.appendChild(opt);
  });
}

function showToast(message) {
  let toast = document.getElementById('card-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'card-toast';
    toast.className = 'card-toast';
    document.body.appendChild(toast);
  }
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => {
    toast.classList.remove('show');
  }, 3500);
}

async function downloadCardPNG() {
  const cardEl = document.querySelector('#card-mount-point .card');
  const btn = document.getElementById('card-btn-download');
  if (!cardEl || !btn) return;

  const originalContent = btn.innerHTML;
  btn.innerHTML = '<span>Menyiapkan Gambar HD (3:4)...</span>';
  btn.disabled = true;

  try {
    if (document.fonts) {
      await document.fonts.ready;
    }

    // Mount unscaled clone in active viewport (opacity: 0) to ensure accurate font and layout metrics
    const off = document.createElement('div');
    off.style.position = 'fixed';
    off.style.left = '0';
    off.style.top = '0';
    off.style.width = '540px';
    off.style.height = '760px';
    off.style.opacity = '0';
    off.style.pointerEvents = 'none';
    off.style.zIndex = '-9999';
    off.style.overflow = 'hidden';

    const clone = cardEl.cloneNode(true);
    clone.style.transform = 'none';
    clone.style.margin = '0';
    off.appendChild(clone);
    document.body.appendChild(off);

    // Run font auto-fit on the 540x760 clone
    fit(clone);

    // Wait for frame to flush layout
    await new Promise(r => setTimeout(r, 120));

    let dataUrl;
    // Prefer htmlToImage (uses native browser rendering engine -> 100% pixel-perfect)
    if (window.htmlToImage && typeof window.htmlToImage.toPng === 'function') {
      dataUrl = await window.htmlToImage.toPng(clone, {
        pixelRatio: 2,
        width: 540,
        height: 760,
        canvasWidth: 1080,
        canvasHeight: 1520,
        cacheBust: true
      });
    } else if (typeof html2canvas === 'function') {
      const canvas = await html2canvas(clone, {
        scale: 2,
        width: 540,
        height: 760,
        backgroundColor: null,
        useCORS: true,
        logging: false
      });
      dataUrl = canvas.toDataURL('image/png');
    }

    document.body.removeChild(off);

    if (dataUrl) {
      const link = document.createElement('a');
      const filename = 'paJAK-Kita-Insight-' + (INS[curIndex].wil || 'Jakarta').replace(/\s+/g, '-') + '-' + Date.now() + '.png';
      link.download = filename;
      link.href = dataUrl;
      link.click();
      showToast('Kartu Insight 3:4 berhasil diunduh!');
    } else {
      alert('Modul pengunduh belum siap. Silakan muat ulang halaman.');
    }
  } catch (err) {
    console.error('Download card error:', err);
    // Ultimate fallback: direct html2canvas on cardEl
    try {
      if (typeof html2canvas === 'function') {
        const canvas = await html2canvas(cardEl, { scale: 2, backgroundColor: null, useCORS: true });
        const link = document.createElement('a');
        link.download = 'paJAK-Kita-Insight-' + Date.now() + '.png';
        link.href = canvas.toDataURL('image/png');
        link.click();
        showToast('Kartu Insight 3:4 berhasil diunduh!');
      }
    } catch (e2) {
      alert('Gagal mengunduh kartu. Silakan coba kembali.');
    }
  } finally {
    btn.innerHTML = originalContent;
    btn.disabled = false;
  }
}

async function shareCard() {
  const currentItem = INS[curIndex];
  const shareData = {
    title: 'Fakta Pajak ' + currentItem.wil + ' — paJAK-Kita',
    text: 'Fakta Pajak di ' + currentItem.wil + ': ' + currentItem.angka + ' (' + currentItem.lbl + '). Pahami transparansi data publik Jakarta di paJAK-Kita!',
    url: window.location.href
  };

  if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
    try {
      await navigator.share(shareData);
    } catch (e) {
      if (e.name !== 'AbortError') console.log('Share dismissed');
    }
  } else {
    try {
      await navigator.clipboard.writeText(window.location.href);
      showToast('Tautan berhasil disalin ke papan klip! Siap dibagikan.');
    } catch (err) {
      downloadCardPNG();
    }
  }
}

function initCardGenerator() {
  const nameInput = document.getElementById('card-input-name');
  const regionSelect = document.getElementById('card-input-region');
  const insightSelect = document.getElementById('card-insight-select');
  const templateRadios = document.querySelectorAll('input[name="card-template"]');
  const randomBtn = document.getElementById('card-btn-randomize');
  const downloadBtn = document.getElementById('card-btn-download');
  const shareBtn = document.getElementById('card-btn-share');

  if (nameInput) {
    curName = nameInput.value.trim() || 'Raihan';
    nameInput.addEventListener('input', (e) => {
      curName = e.target.value.trim() || 'Warga Jakarta';
      renderCardPreview();
    });
  }

  if (regionSelect) {
    curRegion = regionSelect.value;
    regionSelect.addEventListener('change', (e) => {
      curRegion = e.target.value;
      const filtered = getFilteredInsights(curRegion);
      if (filtered.length > 0) {
        curIndex = INS.findIndex(i => i.id === filtered[0].id);
      }
      populateInsightDropdown();
      renderCardPreview();
    });
  }

  if (insightSelect) {
    populateInsightDropdown();
    insightSelect.addEventListener('change', (e) => {
      curIndex = parseInt(e.target.value, 10);
      renderCardPreview();
    });
  }

  templateRadios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      if (e.target.checked) {
        curTemplate = e.target.value;
        document.querySelectorAll('.template-radio-label').forEach(label => {
          label.classList.toggle('active', label.querySelector('input').checked);
        });
        renderCardPreview();
      }
    });
  });

  if (randomBtn) {
    randomBtn.addEventListener('click', () => {
      const filtered = getFilteredInsights(curRegion);
      let nextId = filtered[Math.floor(Math.random() * filtered.length)].id;
      if (filtered.length > 1 && INS[curIndex].id === nextId) {
        const remaining = filtered.filter(i => i.id !== nextId);
        nextId = remaining[Math.floor(Math.random() * remaining.length)].id;
      }
      curIndex = INS.findIndex(i => i.id === nextId);
      populateInsightDropdown();
      renderCardPreview();
      showToast('Fakta insight diperbarui!');
    });
  }

  if (downloadBtn) {
    downloadBtn.addEventListener('click', downloadCardPNG);
  }

  if (shareBtn) {
    shareBtn.addEventListener('click', shareCard);
  }

  window.addEventListener('resize', updateCardPreviewScale);

  // Initial render
  populateInsightDropdown();
  renderCardPreview();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    initCardGenerator();
  });
} else {
  initCardGenerator();
}

window.PajakCards = { DESIGNS, INS, mount, fit, renderCardPreview, initCardGenerator };
